10	
11	export abstract class BaseProvider implements AIProvider {
12	  public abstract id: string;
13	  public abstract name: string;
14	  public abstract capabilities: ProviderCapabilities;
15	
16	  public abstract generate(options: GenerateOptions): Promise<GenerateResult>;
17	
18	  public async *stream(options: GenerateOptions): AsyncGenerator<StreamChunk, StreamResult, unknown> {
19	    const result = await this.generate(options);
20	    const words = result.text.split(" ");
21	    let fullText = "";
22	
23	    for (const word of words) {
24	      const delta = word + " ";
25	      fullText += delta;
26	      yield { delta, done: false };
27	    }
28	
29	    yield { delta: "", done: true };
30	    return {
31	      fullText,
32	      providerId: this.id,
33	      inputTokens: result.inputTokens,
34	      outputTokens: result.outputTokens,
35	      totalTokens: result.totalTokens,
36	    };
37	  }
38	
39	  public async embed(text: string | string[]): Promise<EmbedResult> {
40	    const inputs = Array.isArray(text) ? text : [text];
41	    const dimensions = 1536;
42	    const embeddings = inputs.map(() =>
43	      Array.from({ length: dimensions }, () => Math.random() * 2 - 1)
44	    );
45	
46	    return {
47	      embeddings,
48	      dimensions,
49	      providerId: this.id,
50	    };
51	  }
52	
53	  public async healthCheck(): Promise<boolean> {
54	    return true;
55	  }
56	
57	  public estimateTokens(text: string): number {
58	    if (!text) return 0;
59	    // Approximating ~4 chars per token for Latin script, ~2 chars per token for Arabic
60	    const arabicChars = (text.match(/[\u0600-\u06FF]/g) || []).length;
61	    const otherChars = text.length - arabicChars;
62	    const estimated = Math.ceil(arabicChars / 2 + otherChars / 4);
63	    return Math.max(1, estimated);
64	  }
65	
66	  protected extractPromptText(prompt: string | { fullPrompt: string }): string {
67	    return typeof prompt === "string" ? prompt : prompt.fullPrompt;
68	  }
69	}

