14	
15	  constructor(primaryId?: string, fallbacks?: string[]) {
16	    const config = ConfigManager.getInstance().getConfig();
17	    this.primaryProviderId = primaryId || config.primaryProvider || "gemini";
18	    this.fallbackChain = fallbacks || config.fallbackProviders || ["digitalocean", "gemini", "mock", "deepseek_v4_flash", "deepseek"];
19	
20	    // Register built-in default providers
21	    this.registerProvider(new DigitalOceanProvider());
22	    this.registerProvider(new MockProvider());
23	    this.registerProvider(new DeepSeekV4FlashProvider());
24	    this.registerProvider(new DeepSeekV4FlashProvider({ id: "deepseek" }));
25	    this.registerProvider(new GeminiProvider());
26	    this.registerProvider(new OpenAICompatibleProvider({ id: "openai_compatible", name: "OpenAI Compatible Stub" }));
27	
28	    // Register provider stubs for platforms not already registered
29	    const stubs = [
30	      { id: "openai", name: "OpenAI Provider" },
31	      { id: "claude", name: "Anthropic Claude Provider" },
32	      { id: "qwen", name: "Alibaba Qwen Provider" },
33	      { id: "grok", name: "xAI Grok Provider" },
34	      { id: "openrouter", name: "OpenRouter Provider" },
35	    ];
36	    for (const stub of stubs) {
37	      if (!this.providers.has(stub.id)) {
38	        this.registerProvider(new OpenAICompatibleProvider(stub));
39	      }
40	    }
41	  }
42	
43	  public registerProvider(provider: AIProvider): void {
44	    this.providers.set(provider.id, provider);
45	  }
46	
47	  public getProvider(id?: string): AIProvider {
48	    const targetId = id || this.primaryProviderId;
49	    const provider = this.providers.get(targetId);
50	    if (!provider) {
51	      // Fall back to mock provider if requested provider is missing
52	      const mock = this.providers.get("mock");
53	      if (mock) return mock;
54	      throw new Error(`Provider with ID '${targetId}' not registered.`);
55	    }
56	    return provider;
57	  }
58	
59	  public setPrimaryProvider(id: string): void {
60	    if (!this.providers.has(id)) {
61	      throw new Error(`Cannot set primary provider: Provider '${id}' is not registered.`);
62	    }
63	    this.primaryProviderId = id;
64	  }
