66	  public setFallbackChain(chain: string[]): void {
67	    this.fallbackChain = [...chain];
68	  }
69	
70	  public getRegisteredProviderIds(): string[] {
71	    return Array.from(this.providers.keys());
72	  }
73	
74	  /**
75	   * Generates content using the primary provider.
76	   * If primary fails, automatically attempts fallbacks in order.
77	   */
78	  public async generateWithFallback(options: GenerateOptions): Promise<{
79	    result: GenerateResult;
80	    retriesCount: number;
81	    usedFallback: boolean;
82	  }> {
83	    const candidates = [this.primaryProviderId, ...this.fallbackChain];
84	    const uniqueCandidates = Array.from(new Set(candidates));
85	
86	    let lastError: Error | null = null;
87	    let retriesCount = 0;
88	
89	    for (let i = 0; i < uniqueCandidates.length; i++) {
90	      const providerId = uniqueCandidates[i];
91	      const provider = this.providers.get(providerId);
92	
93	      if (!provider) continue;
94	
95	      try {
96	        const result = await provider.generate(options);
97	        return {
98	          result,
99	          retriesCount,
100	          usedFallback: i > 0,
101	        };
102	      } catch (err: unknown) {
103	        retriesCount++;
104	        lastError = err instanceof Error ? err : new Error(String(err));
105	        console.warn(`[ProviderManager] Provider '${providerId}' failed. Attempting next fallback... Error:`, lastError.message);
106	      }
107	    }
108	
109	    throw new Error(
110	      `All providers in fallback chain failed. Last error: ${lastError?.message || "Unknown error"}`
111	    );
112	  }
113	
114	  public async healthCheckAll(): Promise<Record<string, boolean>> {
115	    const results: Record<string, boolean> = {};
116	    for (const [id, provider] of this.providers.entries()) {
117	      try {
118	        results[id] = await provider.healthCheck();
119	      } catch {
120	        results[id] = false;
121	      }
122	    }
123	    return results;
124	  }
125	}

