4	
5	export class GeminiProvider extends BaseProvider {
6	  public id = "gemini";
7	  public name = "Google Gemini Pool Provider";
8	  public capabilities: ProviderCapabilities = {
9	    supportsStreaming: true,
10	    supportsEmbeddings: true,
11	    supportsVision: true,
12	    maxContextTokens: 128000,
13	  };
14	
15	  private poolManager: GeminiPoolManager;
16	
17	  constructor() {
18	    super();
19	    this.poolManager = GeminiPoolManager.getInstance();
20	  }
21	
22	  public async generate(options: GenerateOptions): Promise<GenerateResult> {
23	    const startTime = Date.now();
24	    const promptText = this.extractPromptText(options.prompt);
25	    const inputTokens = this.estimateTokens(promptText);
26	
27	    // Select optimal Gemini key from multi-account pool
28	    const selectedAccount = this.poolManager.selectBestAccount();
29	
30	    // If sandbox / test mode or secret key unavailable
31	    if (selectedAccount.secretKey.includes("sandbox") || process.env.NODE_ENV === "test") {
32	      const simulatedText = `[Google Gemini Pool (${selectedAccount.keyId})]: تم توليد الشرح والتحليل التعليمي المتقدم بذكاء فائق للمنهج المصري.`;
33	      const outputTokens = this.estimateTokens(simulatedText);
34	      const latency = Date.now() - startTime;
35	
36	      this.poolManager.recordSuccess(selectedAccount.keyId, inputTokens + outputTokens, latency);
37	
38	      return {
39	        text: simulatedText,
40	        providerId: this.id,
41	        providerName: this.name,
42	        inputTokens,
43	        outputTokens,
44	        totalTokens: inputTokens + outputTokens,
45	        latencyMs: latency,
46	      };
47	    }
48	
49	    try {
50	      const controller = new AbortController();
51	      const timeoutId = setTimeout(() => controller.abort(), options.timeoutMs || 15000);
52	
53	      const response = await fetch(
54	        `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent`,
55	        {
56	          method: "POST",
57	          headers: {
58	            "Content-Type": "application/json",
59	            "X-goog-api-key": selectedAccount.secretKey,
60	          },
61	          body: JSON.stringify({
62	            contents: [
63	              {
64	                parts: [{ text: promptText }],
65	              },
66	            ],
67	          }),
68	          signal: controller.signal,
69	        }
70	      );
71	
72	      clearTimeout(timeoutId);
73	
74	      if (response.status === 429) {
75	        this.poolManager.recordRateLimit(selectedAccount.keyId, 60000);
76	        throw new Error(`429 Rate Limit on Gemini account ${selectedAccount.keyId}`);
77	      }
78	
79	      if (response.status === 401 || response.status === 403) {
80	        this.poolManager.recordUnauthorized(selectedAccount.keyId);
81	        throw new Error(`401/403 Unauthorized on Gemini account ${selectedAccount.keyId}`);
82	      }
83	
84	      if (response.status >= 500) {
85	        this.poolManager.recordServerError(selectedAccount.keyId, `Status ${response.status}`);
86	        throw new Error(`5xx Server Error on Gemini account ${selectedAccount.keyId}`);
87	      }
88	
89	      if (!response.ok) {
90	        throw new Error(`Gemini API Error (${response.status})`);
91	      }
92	
93	      const data = await response.json();
94	      const textResult = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
95	      const outputTokens = this.estimateTokens(textResult);
96	      const latency = Date.now() - startTime;
97	
98	      this.poolManager.recordSuccess(selectedAccount.keyId, inputTokens + outputTokens, latency);
99	
100	      return {
101	        text: textResult,
102	        providerId: this.id,
103	        providerName: this.name,
104	        inputTokens,
105	        outputTokens,
106	        totalTokens: inputTokens + outputTokens,
107	        latencyMs: latency,
108	      };
109	    } catch (err: any) {
110	      console.warn(`[GeminiProvider] Key '${selectedAccount.keyId}' failed (${err?.message}). Throwing error for fallback chain.`);
111	      throw err instanceof Error ? err : new Error(String(err));
112	    }
113	  }
114	
115	  public async *stream(options: GenerateOptions): AsyncGenerator<StreamChunk, StreamResult, unknown> {
116	    const result = await this.generate(options);
117	    const words = result.text.split(" ");
118	    let fullText = "";
119	
120	    for (const word of words) {
121	      const delta = word + " ";
122	      fullText += delta;
123	      yield { delta, done: false };
124	    }
125	
126	    yield { delta: "", done: true };
127	    return {
128	      fullText,
129	      providerId: this.id,
130	      inputTokens: result.inputTokens,
131	      outputTokens: result.outputTokens,
132	      totalTokens: result.totalTokens,
133	    };
134	  }
135	}

