1	export type AccountHealth = "Healthy" | "CoolingDown" | "Disabled";
2	
3	export interface AccountStats {
4	  keyId: string;
5	  secretKey: string;
6	  requestsToday: number;
7	  requestsThisMinute: number;
8	  tokensToday: number;
9	  tokensThisMinute: number;
10	  health: AccountHealth;
11	  lastError: string | null;
12	  cooldownUntil: number | null;
13	  averageLatencyMs: number;
14	  remainingQuota: number; // 0 - 100 percentage
15	  scorePenalties: number;
16	  totalSuccesses: number;
17	}
18	
19	export class GeminiPoolManager {
20	  private static instance: GeminiPoolManager;
21	  private accounts: Map<string, AccountStats> = new Map();
22	  private lastResetDay = new Date().getDate();
23	  private lastResetMinute = new Date().getMinutes();
24	
25	  private constructor() {
26	    this.discoverAccountsFromEnv();
27	  }
28	
29	  public static getInstance(): GeminiPoolManager {
30	    if (!GeminiPoolManager.instance) {
31	      GeminiPoolManager.instance = new GeminiPoolManager();
32	    }
33	    return GeminiPoolManager.instance;
34	  }
35	
36	  /**
37	   * Scans process.env for all GEMINI_KEY_* and GEMINI_API_KEY* entries dynamically.
38	   */
39	  public discoverAccountsFromEnv(): void {
40	    const env = process.env;
41	    let found = 0;
42	
43	    for (const [key, value] of Object.entries(env)) {
44	      if ((key.startsWith("GEMINI_KEY_") || key.startsWith("GEMINI_API_KEY")) && value && value.trim().length > 0) {
45	        const keyId = key.toLowerCase();
46	        if (!this.accounts.has(keyId)) {
47	          this.accounts.set(keyId, {
48	            keyId,
49	            secretKey: value.trim(),
50	            requestsToday: 0,
51	            requestsThisMinute: 0,
52	            tokensToday: 0,
53	            tokensThisMinute: 0,
54	            health: "Healthy",
55	            lastError: null,
56	            cooldownUntil: null,
57	            averageLatencyMs: 150,
58	            remainingQuota: 100,
59	            scorePenalties: 0,
60	            totalSuccesses: 0,
61	          });
62	          found++;
63	        }
64	      }
65	    }
66	
67	    // Fallback stub account if no env vars present
68	    if (this.accounts.size === 0) {
69	      this.accounts.set("gemini_default_sandbox", {
70	        keyId: "gemini_default_sandbox",
71	        secretKey: "sandbox_gemini_key",
72	        requestsToday: 0,
73	        requestsThisMinute: 0,
74	        tokensToday: 0,
75	        tokensThisMinute: 0,
76	        health: "Healthy",
77	        lastError: null,
78	        cooldownUntil: null,
79	        averageLatencyMs: 100,
80	        remainingQuota: 100,
81	        scorePenalties: 0,
82	        totalSuccesses: 0,
83	      });
84	    }
85	  }
86	
87	  /**
88	   * Selects the optimal Gemini API account based on composite score:
89	   * Score = RemainingQuota * 35% + Health * 25% + Latency * 15% + MinuteUsage * 15% + DailyUsage * 10%
90	   */
91	  public selectBestAccount(): AccountStats {
92	    this.checkAutoReset();
93	    this.updateCooldownStatuses();
94	
95	    let bestAccount: AccountStats | null = null;
96	    let highestScore = -Infinity;
97	
98	    for (const account of this.accounts.values()) {
99	      if (account.health === "Disabled") continue;
100	
101	      if (account.health === "CoolingDown") {
102	        if (account.cooldownUntil && Date.now() < account.cooldownUntil) {
103	          continue; // Still cooling down
104	        } else {
105	          // Cooldown expired
106	          account.health = "Healthy";
107	          account.cooldownUntil = null;
108	        }
109	      }
110	
111	      const score = this.calculateAccountScore(account);
112	      if (score > highestScore) {
113	        highestScore = score;
114	        bestAccount = account;
115	      }
116	    }
117	
118	    if (!bestAccount) {
119	      // If all accounts cooling down/disabled, pick healthiest or default
120	      const allAccounts = Array.from(this.accounts.values());
121	      bestAccount = allAccounts.find(a => a.health !== "Disabled") || allAccounts[0];
122	    }
123	
124	    return bestAccount;
125	  }
126	
127	  public calculateAccountScore(account: AccountStats): number {
128	    const quotaScore = account.remainingQuota * 0.35;
129	    const healthScore = (account.health === "Healthy" ? 100 : account.health === "CoolingDown" ? 20 : 0) * 0.25;
130	    const latencyScore = Math.max(0, 100 - (account.averageLatencyMs / 20)) * 0.15;
131	    const minuteUsageScore = Math.max(0, 100 - (account.requestsThisMinute * 5)) * 0.15;
132	    const dailyUsageScore = Math.max(0, 100 - (account.requestsToday / 50)) * 0.10;
133	
134	    const total = quotaScore + healthScore + latencyScore + minuteUsageScore + dailyUsageScore - account.scorePenalties;
135	    return Math.max(0, total);
136	  }
137	
138	  public recordSuccess(keyId: string, tokens: number, latencyMs: number): void {
139	    const account = this.accounts.get(keyId);
140	    if (!account) return;
141	
142	    account.requestsToday++;
143	    account.requestsThisMinute++;
144	    account.tokensToday += tokens;
145	    account.tokensThisMinute += tokens;
146	    account.totalSuccesses++;
147	
148	    // Exponential moving average latency calculation
149	    account.averageLatencyMs = Math.round(account.averageLatencyMs * 0.8 + latencyMs * 0.2);
150	
151	    // Slowly recover quota & penalties
152	    account.remainingQuota = Math.max(10, account.remainingQuota - 0.05);
153	    account.scorePenalties = Math.max(0, account.scorePenalties - 1);
154	
155	    // Safe logging (NEVER logs secret key string)
156	    const estimatedCostUsd = (tokens / 1000) * 0.00015;
157	    console.log(
158	      `[GeminiPoolManager] Account '${account.keyId}' Executed Successfully | Tokens: ${tokens} | Latency: ${latencyMs}ms | Est. Cost: $${estimatedCostUsd.toFixed(6)} | Remaining Quota: ${account.remainingQuota.toFixed(1)}%`
159	    );
160	  }
161	
162	  public recordRateLimit(keyId: string, retryAfterMs = 60000): void {
163	    const account = this.accounts.get(keyId);
164	    if (!account) return;
165	
166	    account.health = "CoolingDown";
167	    account.cooldownUntil = Date.now() + retryAfterMs;
168	    account.lastError = `429 Rate Limit (Cooldown ${retryAfterMs / 1000}s)`;
169	    account.remainingQuota = Math.max(5, account.remainingQuota - 20);
170	
171	    console.warn(`[GeminiPoolManager] Account '${account.keyId}' hit 429 Rate Limit. Cooling down for ${retryAfterMs / 1000}s.`);
172	  }
173	
174	  public recordUnauthorized(keyId: string): void {
175	    const account = this.accounts.get(keyId);
176	    if (!account) return;
177	
178	    account.health = "Disabled";
179	    account.lastError = "401 Unauthorized / Invalid API Key";
180	    account.remainingQuota = 0;
181	
182	    console.error(`[GeminiPoolManager] Account '${account.keyId}' returned 401 Unauthorized. Account permanently DISABLED.`);
183	  }
184	
185	  public recordServerError(keyId: string, errorMsg: string): void {
186	    const account = this.accounts.get(keyId);
187	    if (!account) return;
188	
189	    account.scorePenalties += 15;
190	    account.lastError = `5xx Server Error: ${errorMsg}`;
191	
192	    console.warn(`[GeminiPoolManager] Account '${account.keyId}' returned 5xx Server Error. Temporary score penalty applied (+15).`);
193	  }
194	
195	  public getAllAccountStats(): Omit<AccountStats, "secretKey">[] {
196	    return Array.from(this.accounts.values()).map(acc => {
197	      const { secretKey, ...safeStats } = acc;
198	      return safeStats;
199	    });
200	  }
201	
202	  private updateCooldownStatuses(): void {
203	    const now = Date.now();
204	    for (const account of this.accounts.values()) {
205	      if (account.health === "CoolingDown" && account.cooldownUntil && now >= account.cooldownUntil) {
206	        account.health = "Healthy";
207	        account.cooldownUntil = null;
208	      }
209	    }
210	  }
211	
212	  private checkAutoReset(): void {
213	    const now = new Date();
214	
215	    if (now.getDate() !== this.lastResetDay) {
216	      for (const acc of this.accounts.values()) {
217	        acc.requestsToday = 0;
218	        acc.tokensToday = 0;
219	        acc.remainingQuota = 100;
220	      }
221	      this.lastResetDay = now.getDate();
222	    }
223	
224	    if (now.getMinutes() !== this.lastResetMinute) {
225	      for (const acc of this.accounts.values()) {
226	        acc.requestsThisMinute = 0;
227	        acc.tokensThisMinute = 0;
228	      }
229	      this.lastResetMinute = now.getMinutes();
230	    }
231	  }
232	}

1	import { BudgetPolicies } from "./BudgetPolicies";
2	import { BudgetTracker } from "./BudgetTracker";
3	import { BudgetAlerts, BudgetAlertLevel } from "./BudgetAlerts";
4	
5	export interface PreflightResult {
6	  allowed: boolean;
7	  reason?: string;
8	  suggestedProviderId?: string;
9	  estimatedCostUsd: number;
10	  budgetLevel: BudgetAlertLevel | "Normal";
11	  autoMode?: "economy" | "degraded" | "critical" | "emergency";
12	}
13	
14	export class BudgetManager {
15	  private static instance: BudgetManager;
16	
17	  public static getInstance(): BudgetManager {
18	    if (!BudgetManager.instance) {
19	      BudgetManager.instance = new BudgetManager();
20	    }
21	    return BudgetManager.instance;
22	  }
23	
24	  /**
25	   * Pre-flight check: called BEFORE every AI request.
26	   * Estimates cost and decides allow / reject / redirect.
27	   */
28	  public preflight(params: {
29	    providerId: string;
30	    estimatedTokens: number;
31	    action: string;
32	    subject?: string;
33	    grade?: string;
34	    studentId?: string;
35	    teacherId?: string;
36	  }): PreflightResult {
37	    const policies = BudgetPolicies.getInstance();
38	    const tracker = BudgetTracker.getInstance();
39	    const alerts = BudgetAlerts.getInstance();
40	
41	    const estimatedCostUsd = policies.estimateCostUsd(params.providerId, params.estimatedTokens);
42	    const budgetLevel = alerts.getCurrentLevel();
43	
44	    // 1. Emergency: apply policy
45	    if (budgetLevel === "Emergency") {
46	      const ep = policies.getPolicy().emergencyPolicy;
47	      if (ep === "reject") {
48	        return { allowed: false, reason: "تجاوز الميزانية اليومية الكاملة. خدمة الذكاء الاصطناعي متوقفة مؤقتاً.", estimatedCostUsd, budgetLevel };
49	      }
50	      return { allowed: true, suggestedProviderId: ep === "cache_only" ? "mock" : ep, estimatedCostUsd, budgetLevel, autoMode: "emergency" };
51	    }
52	
53	    // 2. Critical: disable expensive actions
54	    if (budgetLevel === "Critical") {
55	      const expensiveActions = ["EXAM", "PLAN", "TEACHER_REPORT", "PARENT_REPORT"];
56	      if (expensiveActions.includes(params.action)) {
57	        return { allowed: false, reason: `الإجراء (${params.action}) معطّل تلقائياً لتجاوز حد الميزانية الحرجة.`, estimatedCostUsd, budgetLevel, autoMode: "critical" };
58	      }
59	      return { allowed: true, suggestedProviderId: "gemini", estimatedCostUsd, budgetLevel, autoMode: "critical" };
60	    }
61	
62	    // 3. Degraded: reduce quality, prefer cheapest provider
63	    if (budgetLevel === "Degraded") {
64	      return { allowed: true, suggestedProviderId: "gemini", estimatedCostUsd, budgetLevel, autoMode: "degraded" };
65	    }
66	
67	    // 4. Economy: aggressive caching, prefer cheaper provider
68	    if (budgetLevel === "Economy") {
69	      return { allowed: true, suggestedProviderId: params.providerId, estimatedCostUsd, budgetLevel, autoMode: "economy" };
70	    }
71	
72	    // 5. Per-student limit check
73	    const policy = policies.getPolicy();
74	    if (params.studentId) {
75	      const studentSpent = tracker.getByStudent(params.studentId);
76	      if (studentSpent + estimatedCostUsd > policy.perStudentDailyUsd) {
77	        return { allowed: false, reason: `تجاوز الطالب الحد اليومي المخصص له من الذكاء الاصطناعي ($${policy.perStudentDailyUsd}).`, estimatedCostUsd, budgetLevel };
78	      }
79	    }
80	
81	    // 6. Per-provider limit check
82	    const providerSpent = tracker.getByProvider(params.providerId);
83	    const providerLimit = policy.perProviderDailyUsd[params.providerId] ?? policy.perProviderDailyUsd["default"] ?? 999;
84	    if (providerSpent + estimatedCostUsd > providerLimit) {
85	      const fallback = params.providerId === "deepseek_v4_flash" ? "gemini" : "mock";
86	      return { allowed: true, suggestedProviderId: fallback, estimatedCostUsd, budgetLevel, reason: `تجاوز حد المزوّد ${params.providerId}. التحويل التلقائي إلى ${fallback}.` };
87	    }
88	
89	    // Emit alerts & allow
90	    alerts.checkAndEmit();
91	    return { allowed: true, estimatedCostUsd, budgetLevel };
92	  }
93	
94	  public recordActualCost(params: {
95	    costUsd: number;
96	    providerId: string;
97	    subject?: string;
98	    grade?: string;
99	    studentId?: string;
100	    teacherId?: string;
101	    action?: string;
102	    apiKeyId?: string;
103	  }): void {
104	    BudgetTracker.getInstance().record(params);
105	    BudgetAlerts.getInstance().checkAndEmit();
