74	  private checkAutoReset(): void {
75	    const now = new Date();
76	    if (now.getDate() !== this.spending.lastResetDay) {
77	      this.spending.globalDailyUsd = 0;
78	      this.spending.byProvider = {};
79	      this.spending.bySubject = {};
80	      this.spending.byGrade = {};
81	      this.spending.byStudent = {};
