33	  public emit(params: Omit<SystemAlert, "id" | "timestamp" | "resolved">): SystemAlert {
34	    const alert: SystemAlert = {
35	      ...params,
36	      id: `alt_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
37	      timestamp: new Date().toISOString(),
38	      resolved: false,
39	    };
40	
41	    this.alerts.push(alert);
42	    if (this.alerts.length > this.MAX_ALERTS) this.alerts.shift();
43	
44	    const emoji = { Info: "ℹ️", Warning: "⚠️", Error: "🔴", Critical: "🚨" }[params.severity];
