495	        if (p.chatHistory || p.studentInfo) {
496	          const parts: string[] = [];
497	          if (p.studentInfo) parts.push(`📋 بيانات المتعلم:\n${p.studentInfo}`);
498	          if (p.chatHistory) parts.push(`💬 سجل المحادثة:\n${p.chatHistory}`);
499	          aiResponse = parts.join("\n\n");
500	        }
501	
502	        const ticket = await prisma.supportTicket.create({
503	          data: {
504	            studentId,
505	            courseId: p.courseId ?? null,
506	            title: p.title,
507	            description: p.description,
508	            type: p.type || "complaint",
509	            priority: p.priority || "normal",
510	            aiHandled: true,
511	            aiResponse,
512	            status: "open",
513	          },
514	        });
515	
516	        return { type: action.type, status: "created", id: ticket.id };
517	      }
518	
519	      case "submit_feedback": {
520	        const p = action.payload as {
521	          courseId: string;
522	          type: string;
523	          content: string;
524	          rating?: number;
525	        };
526	        if (!p?.courseId || !p?.content) {
527	          return { type: action.type, status: "failed", error: "بيانات ناقصة" };
528	        }
529	
530	        const { checkCourseEnrollment } = await import("@/lib/authorization");
531	        const isEnrolled = await checkCourseEnrollment(studentId, p.courseId);
532	        if (!isEnrolled) {
533	          return { type: action.type, status: "failed", error: "غير مسجل في هذا الكورس" };
534	        }
535	
536	        const course = await prisma.course.findUnique({
537	          where: { id: p.courseId },
538	          select: { teacherId: true },
539	        });
540	        if (!course) {
541	          return { type: action.type, status: "failed", error: "الكورس غير موجود" };
542	        }
543	
544	        const fb = await prisma.studentFeedback.create({
545	          data: {
546	            studentId,
547	            courseId: p.courseId,
548	            teacherId: course.teacherId,
549	            type: p.type || "other",
550	            content: p.content,
551	            rating: p.rating ?? null,
552	            aiAnalyzed: true,
553	          },
554	        });
555	
556	        return { type: action.type, status: "created", id: fb.id };
557	      }
558	
559	      case "navigate":
560	      case "show_insights":
561	      case "none":
562	        return { type: action.type, status: "ok" };
563	
564	      default:
565	        return { type: "unknown", status: "ignored" };
566	    }
567	  } catch (err) {
568	    console.error("Action execution error:", err);
569	    return {
570	      type: action.type,
571	      status: "failed",
572	      error: err instanceof Error ? err.message : "خطأ غير معروف",
573	    };
574	  }
575	}

