1	import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
2	import { prisma } from "./prisma";
3	
4	/**
5	 * AI provider management. API keys are encrypted with AES-256-GCM before they
6	 * touch the database and are NEVER returned to the client — getActiveProviders()
7	 * exposes only a `hasKey` boolean. Decryption happens server-side, only inside
8	 * AI request handlers, via getDecryptedKey().
9	 */
10	
11	// ── Encryption ──────────────────────────────────────────────────────────────
12	// The 32-byte AES key is derived (sha256) from CONFIG_ENCRYPTION_KEY so any
13	// passphrase length works; the env var itself never lands in the DB.
14	function aesKey(): Buffer {
15	  const secret = process.env.CONFIG_ENCRYPTION_KEY;
16	  if (!secret) throw new Error("CONFIG_ENCRYPTION_KEY is not set");
17	  return createHash("sha256").update(secret).digest();
18	}
19	
20	/** Returns "iv:authTag:ciphertext" (all base64). */
21	export function encryptSecret(plaintext: string): string {
22	  // Refuse to encrypt under a weak passphrase. SHA-256 gives no key-stretching,
23	  // so the security is only as strong as this string — require ≥32 chars.
24	  const secret = process.env.CONFIG_ENCRYPTION_KEY ?? "";
25	  if (secret.length < 32) {
26	    throw new Error("CONFIG_ENCRYPTION_KEY must be at least 32 characters (use a long random string)");
27	  }
28	  const iv = randomBytes(12);
29	  const cipher = createCipheriv("aes-256-gcm", aesKey(), iv);
30	  const enc = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
31	  const tag = cipher.getAuthTag();
32	  return `${iv.toString("base64")}:${tag.toString("base64")}:${enc.toString("base64")}`;
33	}
34	
35	function decryptSecret(payload: string): string {
36	  const [ivB64, tagB64, dataB64] = payload.split(":");
37	  if (!ivB64 || !tagB64 || !dataB64) throw new Error("Malformed ciphertext");
38	  const decipher = createDecipheriv("aes-256-gcm", aesKey(), Buffer.from(ivB64, "base64"));
39	  decipher.setAuthTag(Buffer.from(tagB64, "base64"));
40	  return Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]).toString("utf8");
41	}
42	
43	export function encryptionConfigured(): boolean {
44	  return (process.env.CONFIG_ENCRYPTION_KEY?.length ?? 0) >= 32;
45	}
46	
47	// ── Public (no-secret) shapes ────────────────────────────────────────────────
48	export interface PublicProvider {
49	  id: string;
50	  name: string;
51	  slug: string;
52	  baseUrl: string;
53	  models: string[];
54	  hasKey: boolean;
55	  isPrimary: boolean;
56	  isBackup: boolean;
57	  isActive: boolean;
58	}
59	
60	function toPublic(p: {
61	  id: string; name: string; slug: string; baseUrl: string; models: string;
62	  apiKeyEnc: string | null; isPrimary: boolean; isBackup: boolean; isActive: boolean;
63	}): PublicProvider {
64	  let models: string[] = [];
65	  try {
66	    const parsed = JSON.parse(p.models);
67	    if (Array.isArray(parsed)) models = parsed.map(String);
68	  } catch {
69	    /* leave empty */
70	  }
71	  return {
72	    id: p.id,
73	    name: p.name,
74	    slug: p.slug,
75	    baseUrl: p.baseUrl,
76	    models,
77	    hasKey: !!p.apiKeyEnc, // never the key itself
78	    isPrimary: p.isPrimary,
79	    isBackup: p.isBackup,
80	    isActive: p.isActive,
81	  };
82	}
83	
84	/** All providers, keys stripped — safe to send to the client. */
85	export async function getActiveProviders(): Promise<PublicProvider[]> {
86	  try {
87	    const rows = await prisma.aIProvider.findMany({ orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }] });
88	    return rows.map(toPublic);
89	  } catch {
90	    return []; // table missing / db error → empty list, no crash
91	  }
92	}
93	
94	export function normalizeModels(models: unknown): string {
95	  if (Array.isArray(models)) {
96	    return JSON.stringify(models.map((m) => String(m).trim()).filter(Boolean));
97	  }
98	  if (typeof models === "string") {
99	    return JSON.stringify(
100	      models.split(/[\n,]/).map((m) => m.trim()).filter(Boolean)
101	    );
102	  }
103	  return "[]";
104	}
105	
106	// ── Server-only secret access ────────────────────────────────────────────────
107	/** Decrypts a provider's key. Server-only; never call from client code. */
108	export async function getDecryptedKey(providerId: string): Promise<string | null> {
109	  const p = await prisma.aIProvider.findUnique({ where: { id: providerId }, select: { apiKeyEnc: true } });
110	  if (!p?.apiKeyEnc) return null;
111	  try {
112	    return decryptSecret(p.apiKeyEnc);
113	  } catch {
114	    return null;
115	  }
116	}
117	
118	/** Detected request shape for a provider, from its base URL. */
119	export type ProviderKind = "anthropic" | "gemini" | "openai";
120	export function providerKind(baseUrl: string): ProviderKind {
121	  const u = baseUrl.toLowerCase();
122	  if (u.includes("anthropic")) return "anthropic";
123	  if (u.includes("googleapis") || u.includes("generativelanguage")) return "gemini";
124	  return "openai";
125	}
126	
127	export interface ResolvedProvider {
128	  id: string;
129	  name: string;
130	  baseUrl: string;
131	  model: string;
132	  kind: ProviderKind;
133	  key: string;
134	}
135	
136	async function resolveOne(
137	  where: { isPrimary: true } | { isBackup: true }
138	): Promise<ResolvedProvider | null> {
139	  let p;
140	  try {
141	    p = await prisma.aIProvider.findFirst({ where: { ...where, isActive: true } });
142	  } catch {
143	    return null; // table missing / db error → no provider, falls back to default plan
144	  }
145	  if (!p || !p.apiKeyEnc) return null;
146	  let model = "";
147	  try {
148	    const parsed = JSON.parse(p.models);
149	    if (Array.isArray(parsed) && parsed.length) model = String(parsed[0]);
150	  } catch {
151	    /* no model */
152	  }
153	  if (!model) return null;
154	  let key: string;
155	  try {
156	    key = decryptSecret(p.apiKeyEnc);
157	  } catch {
158	    return null;
159	  }
160	  return { id: p.id, name: p.name, baseUrl: p.baseUrl, model, kind: providerKind(p.baseUrl), key };
161	}
162	
163	/** The active primary / backup providers with decrypted keys — server-only. */
164	export async function resolvePlanProviders(): Promise<{
165	  primary: ResolvedProvider | null;
166	  backup: ResolvedProvider | null;
167	}> {
168	  let [primary, backup] = await Promise.all([
169	    resolveOne({ isPrimary: true }),
170	    resolveOne({ isBackup: true }),
171	  ]);
172	
173	  if (!primary && process.env.AI_PRIMARY_API_KEY) {
174	    const baseUrl = process.env.AI_PRIMARY_BASE_URL || "https://api.anthropic.com/v1/messages";
175	    primary = {
176	      id: "env-primary",
177	      name: "Primary AI (ENV)",
178	      baseUrl,
179	      model: process.env.AI_PRIMARY_MODEL || "claude-3-5-sonnet-20241022",
180	      kind: providerKind(baseUrl),
181	      key: process.env.AI_PRIMARY_API_KEY,
182	    };
183	  }
184	
185	  if (!backup && (process.env.AI_BACKUP_API_KEY || process.env.GEMINI_API_KEY)) {
186	    const key = process.env.AI_BACKUP_API_KEY || process.env.GEMINI_API_KEY || "";
187	    const rawBase = process.env.AI_BACKUP_BASE_URL || "https://generativelanguage.googleapis.com/v1beta";
188	    const baseUrl = rawBase.replace(/\/+$/, "").replace(/\/models$/, "");
189	    backup = {
190	      id: "env-backup",
191	      name: "Backup AI (ENV)",
192	      baseUrl,
193	      model: process.env.AI_BACKUP_MODEL || "gemini-2.0-flash-lite",
194	      kind: providerKind(baseUrl),
195	      key,
196	    };
197	  }
198	
199	  // A backup that's the same provider as the primary is not a real fallback —
200	  // ignore it so retrying actually hits a different provider.
201	  if (primary && backup && backup.id === primary.id) {
202	    return { primary, backup: null };
203	  }
204	  return { primary, backup };
205	}

