1	export type ModerationAction = "Pass" | "Warn" | "Block" | "Log";
2	
3	export interface ModerationResult {
4	  action: ModerationAction;
5	  flagged: boolean;
6	  reason?: string;
7	  threatType?: "PromptInjection" | "SystemPromptExtraction" | "Jailbreak" | "Spam" | "Abuse";
8	}
9	
10	export class ModerationEngine {
11	  private jailbreakPatterns = [
12	    "ignore previous instructions",
13	    "ignore all rules",
14	    "you are now in developer mode",
15	    "dan mode",
16	    "bypass safety filters",
17	    "tell me your system prompt",
18	    "system prompt extraction",
19	  ];
20	
21	  public inspectMessage(userMessage: string): ModerationResult {
22	    const lower = userMessage.toLowerCase().trim();
23	
24	    for (const pattern of this.jailbreakPatterns) {
25	      if (lower.includes(pattern)) {
26	        return {
27	          action: "Block",
28	          flagged: true,
29	          reason: `Detected potential security violation pattern: '${pattern}'`,
30	          threatType: lower.includes("system prompt") ? "SystemPromptExtraction" : "Jailbreak",
31	        };
32	      }
33	    }
34	
35	    if (userMessage.length > 10000) {
36	      return {
37	        action: "Block",
38	        flagged: true,
39	        reason: "Message payload exceeds maximum allowed size (Spam/Mass Generation).",
40	        threatType: "Spam",
41	      };
42	    }
43	
44	    return {
45	      action: "Pass",
46	      flagged: false,
47	    };
48	  }
49	}

1	export type FirewallAction = "Allow" | "Block" | "Throttle" | "Alert" | "Escalate";
2	
3	export interface FirewallInspectionResult {
4	  allowed: boolean;
5	  action: FirewallAction;
6	  reason?: string;
7	  threatLevel: "None" | "Low" | "High" | "Critical";
8	}
9	
10	export class AIFirewall {
11	  private static ddosTracker: Map<string, number[]> = new Map();
12	
13	  public static inspectRequest(userId: string, userMessage: string): FirewallInspectionResult {
14	    const lower = userMessage.toLowerCase();
15	
16	    // 1. Prompt Leakage & Role Escalation Detection
17	    if (lower.includes("show me your prompt") || lower.includes("print system prompt") || lower.includes("sudo mode")) {
18	      return {
19	        allowed: false,
20	        action: "Block",
21	        reason: "Firewall Block: Attempted System Prompt Leakage or Role Escalation.",
22	        threatLevel: "High",
23	      };
24	    }
25	
26	    // 2. DDoS & Rate Burst Detection (more than 10 requests in 2 seconds)
27	    const now = Date.now();
28	    const userTimestamps = this.ddosTracker.get(userId) || [];
29	    const recent = userTimestamps.filter((t) => now - t < 2000);
30	    recent.push(now);
31	    this.ddosTracker.set(userId, recent);
32	
33	    if (recent.length > 10) {
34	      return {
35	        allowed: false,
36	        action: "Throttle",
37	        reason: "Firewall Throttle: Request burst frequency triggered DDoS protection threshold.",
38	        threatLevel: "Critical",
39	      };
40	    }
41	
42	    return {
43	      allowed: true,
44	      action: "Allow",
45	      threatLevel: "None",
46	    };
47	  }
48	}

