11	    maxHourlyCostUsd: 10.0,
12	    maxCostPerStudentUsd: 2.0,
13	  };
14	
15	  private dailySpent = 0;
16	  private hourlySpent = 0;
17	  private studentSpent: Map<string, number> = new Map();
18	  private lastResetDay = new Date().getDate();
19	  private lastResetHour = new Date().getHours();
20	
21	  public static getInstance(): DailyBudgetManager {
22	    if (!DailyBudgetManager.instance) {
23	      DailyBudgetManager.instance = new DailyBudgetManager();
24	    }
25	    return DailyBudgetManager.instance;
26	  }
27	
28	  public checkBudget(userId = "anon", estimatedCostUsd = 0.001): { allowed: boolean; reason?: string } {
29	    this.checkAutoReset();
30	
31	    if (this.dailySpent + estimatedCostUsd > this.config.maxDailyCostUsd) {
32	      return { allowed: false, reason: "تجاوزت المنصة الحد الأقصى للميزانية اليومية المخصصة للذكاء الاصطناعي." };
33	    }
34	
35	    if (this.hourlySpent + estimatedCostUsd > this.config.maxHourlyCostUsd) {
36	      return { allowed: false, reason: "تجاوزت المنصة الحد الأقصى للميزانية الساعية المخصصة." };
37	    }
38	
39	    const currentStudentSpent = this.studentSpent.get(userId) || 0;
40	    if (currentStudentSpent + estimatedCostUsd > this.config.maxCostPerStudentUsd) {
41	      return { allowed: false, reason: "تجاوز الطالب الحد الأقصى للميزانية اليومية الفردية." };
