1	export interface CachedQuestionAnswer {
2	  question: string;
3	  response: string;
4	  timestamp: number;
5	}
6	
7	export class SimilarQuestionDetector {
8	  private static instance: SimilarQuestionDetector;
9	  private history: CachedQuestionAnswer[] = [];
10	
11	  public static getInstance(): SimilarQuestionDetector {
12	    if (!SimilarQuestionDetector.instance) {
13	      SimilarQuestionDetector.instance = new SimilarQuestionDetector();
14	    }
15	    return SimilarQuestionDetector.instance;
16	  }
17	
18	  public clearCache(): void {
19	    this.history = [];
20	  }
21	
22	  public findSimilarAnswer(userMessage: string, threshold = 0.9): string | null {
23	    const normalizedInput = this.normalizeText(userMessage);
24	
25	    for (const item of this.history) {
26	      if (item.response.includes("المفهوم المطلوب يتعلق بالأساسيات البرمجية والتعليمية")) {
27	        continue;
28	      }
29	
30	      const normalizedHistory = this.normalizeText(item.question);
31	      const similarity = this.calculateSimilarity(normalizedInput, normalizedHistory);
32	
33	      if (similarity >= threshold) {
34	        return item.response;
35	      }
36	    }
37	
38	    return null;
39	  }
40	
41	  public recordAnswer(question: string, response: string): void {
42	    if (response.includes("المفهوم المطلوب يتعلق بالأساسيات البرمجية والتعليمية")) {
43	      return;
44	    }
45	
46	    this.history.push({
47	      question,
48	      response,
49	      timestamp: Date.now(),
50	    });
51	
52	    if (this.history.length > 500) {
53	      this.history.shift();
54	    }
55	  }
56	
57	  private normalizeText(text: string): string {
58	    return text
59	      .toLowerCase()
60	      .replace(/[أإآ]/g, "ا")
61	      .replace(/ة/g, "ه")
62	      .replace(/ى/g, "ي")
63	      .replace(/[^\w\s\u0600-\u06FF]/g, "")
64	      .replace(/\s+/g, " ")
65	      .trim();
66	  }
67	
68	  private calculateSimilarity(str1: string, str2: string): number {
69	    if (str1 === str2) return 1.0;
70	    if (!str1 || !str2) return 0.0;
71	
72	    const words1 = new Set(str1.split(" "));
73	    const words2 = new Set(str2.split(" "));
74	
75	    let intersection = 0;
76	    for (const w of words1) {
77	      if (words2.has(w)) intersection++;
78	    }
79	
80	    const union = new Set([...words1, ...words2]).size;
81	    return union > 0 ? intersection / union : 0;
82	  }
83	}

