6	
7	export interface GatewayExecutionResult {
8	  result: GenerateResult;
9	  modelTier: string;
10	  costEstimateUsd: number;
11	  rateLimitStatus: { remaining: number };
12	  abVariant: string;
13	}
14	
15	export class AIGateway {
16	  private providerManager: ProviderManager;
17	  private rateLimiter: RateLimiter;
18	  private modelRouter: TaskModelRouter;
19	  private abTester: ABTester;
20	  private costPer1kInput = 0.0015; // USD
21	  private costPer1kOutput = 0.006;  // USD
22	
23	  constructor(providerManager?: ProviderManager) {
24	    this.providerManager = providerManager || new ProviderManager();
25	    this.rateLimiter = new RateLimiter();
26	    this.modelRouter = new TaskModelRouter();
27	    this.abTester = ABTester.getInstance();
28	  }
29	
30	  public async executeRequest(
31	    userId: string,
32	    action: EducationalActionType,
33	    options: GenerateOptions
34	  ): Promise<GatewayExecutionResult> {
35	    // 1. Rate Limiting Check
36	    const rateCheck = this.rateLimiter.checkRateLimit(userId);
37	    if (!rateCheck.allowed) {
38	      throw new Error(`Rate limit exceeded for user '${userId}'. Reset in ${Math.ceil(rateCheck.resetMs / 1000)}s.`);
39	    }
40	
41	    // 2. Task Model Routing
42	    const modelSelection = this.modelRouter.routeTask(action);
43	
44	    // 3. A/B Testing Variant Selection
45	    const abResult = this.abTester.getVariant(userId);
46	
47	    // 4. Provider Generation with Fallback
48	    const { result } = await this.providerManager.generateWithFallback(options);
49	
50	    // 5. Cost & Token Accounting
51	    const costEstimateUsd =
52	      (result.inputTokens / 1000) * this.costPer1kInput +
53	      (result.outputTokens / 1000) * this.costPer1kOutput;
54	
55	    return {
56	      result,
57	      modelTier: modelSelection.tier,
58	      costEstimateUsd,
59	      rateLimitStatus: { remaining: rateCheck.remainingRequests },
60	      abVariant: abResult.variant,
61	    };
62	  }
63	
64	  public getProviderManager(): ProviderManager {
65	    return this.providerManager;
66	  }
67	}

