1	export interface RateLimitStatus {
2	  allowed: boolean;
3	  remainingRequests: number;
4	  resetMs: number;
5	}
6	
7	export class RateLimiter {
8	  private requestsMap: Map<string, number[]> = new Map();
9	  private maxRequestsPerWindow = 60; // 60 requests
10	  private windowMs = 60000; // 1 minute
11	
12	  public checkRateLimit(key: string, limitOverride?: number): RateLimitStatus {
13	    const now = Date.now();
14	    const timestamps = this.requestsMap.get(key) || [];
15	    const validTimestamps = timestamps.filter((t) => now - t < this.windowMs);
16	
17	    const max = limitOverride || this.maxRequestsPerWindow;
18	    if (validTimestamps.length >= max) {
19	      const oldest = validTimestamps[0];
20	      const resetMs = this.windowMs - (now - oldest);
21	      return { allowed: false, remainingRequests: 0, resetMs };
22	    }
23	
24	    validTimestamps.push(now);
25	    this.requestsMap.set(key, validTimestamps);
26	
27	    return {
28	      allowed: true,
29	      remainingRequests: max - validTimestamps.length,
30	      resetMs: 0,
31	    };
32	  }
33	}

