39	
40	    // Stub behavior when key is not configured or in testing environment
41	    if (!this.apiKey && !process.env.ALLOW_OFFLINE_MOCK) {
42	      const stubText = `[${this.name} (${this.model}) Stub Response]\n` +
43	        `API Key not configured. The AI engine architecture successfully processed the prompt:\n\n` +
44	        `Prompt summary: ${promptText.slice(0, 150)}...`;
