66	        body: JSON.stringify({
67	          model: this.model,
68	          messages: [
69	            ...(options.systemPrompt
70	              ? [{ role: "system", content: options.systemPrompt }]
71	              : []),
72	            { role: "user", content: promptText },
73	          ],
