81	      }
82	
83	      const data = (await response.json()) as {
84	        choices: Array<{ message: { content: string }; finish_reason: string }>;
85	        usage?: { prompt_tokens: number; completion_tokens: number; total_tokens: number };
86	      };
87	
88	      const text = data.choices[0]?.message?.content || "";
89	      const actualInputTokens = data.usage?.prompt_tokens ?? inputTokens;
90	      const actualOutputTokens = data.usage?.completion_tokens ?? this.estimateTokens(text);
91	
92	      return {
93	        text,
94	        providerId: this.id,
95	        providerName: this.name,
96	        inputTokens: actualInputTokens,
97	        outputTokens: actualOutputTokens,
98	        totalTokens: actualInputTokens + actualOutputTokens,
99	        latencyMs: Date.now() - startTime,
100	        finishReason: data.choices[0]?.finish_reason || "stop",
101	      };
102	    } catch (err: unknown) {
103	      const message = err instanceof Error ? err.message : String(err);
104	      throw new Error(`Provider [${this.id}] generation failed: ${message}`);
105	    }
106	  }
