1	import { ToolRegistry } from "../registry/ToolRegistry";
2	import { PermissionManager } from "../permissions/PermissionManager";
3	import { ToolCache } from "../cache/ToolCache";
4	import { ToolObservability } from "../observability/ToolObservability";
5	import { ToolExecutionContext, ToolExecutionResult } from "../types";
6	
7	export interface ToolChainStep {
8	  toolName: string;
9	  params?: Record<string, unknown>;
10	}
11	
12	export class ToolChainer {
13	  private registry: ToolRegistry;
14	  private cache: ToolCache;
15	  private observability: ToolObservability;
16	
17	  constructor(registry?: ToolRegistry) {
18	    this.registry = registry || ToolRegistry.getInstance();
19	    this.cache = ToolCache.getInstance();
20	    this.observability = ToolObservability.getInstance();
21	  }
22	
23	  public async executeChain(
24	    context: ToolExecutionContext,
25	    steps: ToolChainStep[]
26	  ): Promise<ToolExecutionResult[]> {
27	    const results: ToolExecutionResult[] = [];
28	
29	    for (const step of steps) {
30	      const tool = this.registry.getTool(step.toolName);
31	      if (!tool) {
32	        results.push({
33	          success: false,
34	          data: null,
35	          error: `Tool '${step.toolName}' not found in registry.`,
36	          executionTimeMs: 0,
37	        });
38	        continue;
39	      }
40	
41	      // Permission Check
42	      try {
43	        PermissionManager.checkPermission(tool, context.userRole);
44	      } catch (err: unknown) {
45	        const errorMsg = err instanceof Error ? err.message : String(err);
46	        this.observability.logExecution({
47	          toolName: tool.name,
48	          userId: context.userId,
49	          userRole: context.userRole,
50	          executionTimeMs: 0,
51	          success: false,
52	          cacheHit: false,
53	          error: errorMsg,
54	        });
55	        results.push({
56	          success: false,
57	          data: null,
58	          error: errorMsg,
59	          executionTimeMs: 0,
60	        });
61	        continue;
62	      }
63	
64	      // Cache Lookup
65	      const cacheKey = `${tool.name}_${context.userId}_${JSON.stringify(step.params || {})}`;
66	      if (tool.cacheable) {
67	        const cached = this.cache.get(cacheKey);
68	        if (cached) {
69	          this.observability.logExecution({
70	            toolName: tool.name,
71	            userId: context.userId,
72	            userRole: context.userRole,
73	            executionTimeMs: cached.executionTimeMs,
74	            success: true,
75	            cacheHit: true,
76	          });
77	          results.push(cached);
78	          continue;
79	        }
80	      }
81	
82	      // Execute Tool
83	      const startTime = Date.now();
84	      try {
85	        const res = await tool.execute(context, step.params);
86	        const duration = Date.now() - startTime;
87	
88	        if (tool.cacheable && res.success) {
89	          this.cache.set(cacheKey, res, tool.ttlMs);
90	        }
91	
92	        this.observability.logExecution({
93	          toolName: tool.name,
94	          userId: context.userId,
95	          userRole: context.userRole,
96	          executionTimeMs: duration,
97	          success: res.success,
98	          cacheHit: false,
99	          error: res.error,
100	        });
101	
102	        results.push(res);
103	      } catch (err: unknown) {
104	        const duration = Date.now() - startTime;
105	        const errorMsg = err instanceof Error ? err.message : String(err);
106	        this.observability.logExecution({
107	          toolName: tool.name,
108	          userId: context.userId,
109	          userRole: context.userRole,
110	          executionTimeMs: duration,
111	          success: false,
112	          cacheHit: false,
113	          error: errorMsg,
114	        });
115	        results.push({
116	          success: false,
117	          data: null,
118	          error: errorMsg,
119	          executionTimeMs: duration,
120	        });
121	      }
122	    }
123	
124	    return results;
125	  }
126	}

