3	interface CacheEntry {
4	  result: ToolExecutionResult;
5	  expiresAt: number;
6	}
7	
8	export class ToolCache {
9	  private static instance: ToolCache;
10	  private cache: Map<string, CacheEntry> = new Map();
11	
12	  public static getInstance(): ToolCache {
13	    if (!ToolCache.instance) {
14	      ToolCache.instance = new ToolCache();
15	    }
16	    return ToolCache.instance;
17	  }
18	
19	  public get(key: string): ToolExecutionResult | undefined {
20	    const entry = this.cache.get(key);
21	    if (!entry) return undefined;
22	
23	    if (Date.now() > entry.expiresAt) {
24	      this.cache.delete(key);
25	      return undefined;
26	    }
27	
28	    return { ...entry.result, fromCache: true };
29	  }
30	
31	  public set(key: string, result: ToolExecutionResult, ttlMs = 300000): void {
32	    this.cache.set(key, {
33	      result,
34	      expiresAt: Date.now() + ttlMs,
35	    });
36	  }
37	
38	  public invalidate(prefixOrKey: string): void {
39	    for (const key of this.cache.keys()) {
40	      if (key.includes(prefixOrKey)) {
41	        this.cache.delete(key);
42	      }
43	    }
44	  }
45	
46	  public clear(): void {
47	    this.cache.clear();
48	  }
49	}

