1	import { BudgetTracker } from "./BudgetTracker";
2	import { BudgetPolicies } from "./BudgetPolicies";
3	
4	export type BudgetAlertLevel = "Warning" | "Economy" | "Degraded" | "Critical" | "Emergency";
5	
6	export interface BudgetAlert {
7	  id: string;
8	  level: BudgetAlertLevel;
9	  message: string;
10	  usagePercent: number;
11	  spentUsd: number;
12	  limitUsd: number;
13	  timestamp: string;
14	}
15	
16	export class BudgetAlerts {
17	  private static instance: BudgetAlerts;
18	  private alerts: BudgetAlert[] = [];
19	  private emittedLevels: Set<BudgetAlertLevel> = new Set();
20	
21	  public static getInstance(): BudgetAlerts {
22	    if (!BudgetAlerts.instance) {
23	      BudgetAlerts.instance = new BudgetAlerts();
24	    }
25	    return BudgetAlerts.instance;
26	  }
27	
28	  public checkAndEmit(): BudgetAlert | null {
29	    const tracker = BudgetTracker.getInstance();
30	    const policy = BudgetPolicies.getInstance().getPolicy();
31	    const spent = tracker.getGlobalDaily();
32	    const limit = policy.globalDailyBudgetUsd;
33	    const ratio = spent / limit;
34	
35	    let level: BudgetAlertLevel | null = null;
36	    let message = "";
37	
38	    if (ratio >= policy.emergencyThreshold) {
39	      level = "Emergency";
40	      message = `🚨 AI Budget EMERGENCY: Daily limit $${limit} fully consumed ($${spent.toFixed(4)} spent). Emergency policy activated.`;
41	    } else if (ratio >= policy.criticalThreshold) {
42	      level = "Critical";
43	      message = `🔴 AI Budget CRITICAL: ${(ratio * 100).toFixed(1)}% of daily limit used. Expensive actions disabled.`;
44	    } else if (ratio >= policy.degradedThreshold) {
45	      level = "Degraded";
46	      message = `🟠 AI Budget DEGRADED: ${(ratio * 100).toFixed(1)}% used. Switching to reduced-quality mode.`;
47	    } else if (ratio >= policy.economyThreshold) {
48	      level = "Economy";
49	      message = `🟡 AI Budget Economy Mode: ${(ratio * 100).toFixed(1)}% of daily budget used.`;
50	    } else if (ratio >= policy.warningThreshold) {
51	      level = "Warning";
52	      message = `⚠️ AI Budget Warning: ${(ratio * 100).toFixed(1)}% of daily budget used.`;
53	    }
54	
55	    if (level && !this.emittedLevels.has(level)) {
56	      const alert: BudgetAlert = {
57	        id: `ba_${Date.now()}`,
58	        level,
59	        message,
60	        usagePercent: Math.round(ratio * 100),
61	        spentUsd: spent,
62	        limitUsd: limit,
63	        timestamp: new Date().toISOString(),
64	      };
65	      this.alerts.push(alert);
66	      if (this.alerts.length > 200) this.alerts.shift();
67	      this.emittedLevels.add(level);
68	      console.warn(`[BudgetAlerts] ${message}`);
69	      return alert;
70	    }
71	
72	    return null;
73	  }
74	
75	  public getCurrentLevel(): BudgetAlertLevel | "Normal" {
76	    const tracker = BudgetTracker.getInstance();
77	    const policy = BudgetPolicies.getInstance().getPolicy();
78	    const ratio = tracker.getGlobalDaily() / policy.globalDailyBudgetUsd;
