126	async function callPrimary(messages: ChatMessage[]): Promise<AIChatResult | null> {
127	  if (!PRIMARY_API_KEY) return null;
128	  try {
129	    const sys = messages.find((m) => m.role === "system")?.content || "";
130	    const userMsgs = messages.filter((m) => m.role !== "system");
131	    const res = await fetch(PRIMARY_API_URL, {
132	      method: "POST",
133	      headers: {
134	        "Content-Type": "application/json",
135	        "x-api-key": PRIMARY_API_KEY,
136	        "anthropic-version": "2023-06-01",
137	      },
138	      body: JSON.stringify({
139	        model: PRIMARY_MODEL,
140	        max_tokens: 1200,
141	        temperature: 0.6,
142	        system: sys,
143	        messages: userMsgs.map((m) => ({ role: m.role, content: m.content })),
144	      }),
145	      signal: AbortSignal.timeout(15000),
146	    });
147	    if (!res.ok) throw new Error(`Primary API: ${res.status}`);
148	    const data = (await res.json()) as { content: Array<{ text: string }> };
149	    const raw = data.content[0]?.text || "{}";
150	    // Find first JSON object in response
151	    const match = raw.match(/\{[\s\S]*\}/);
152	    const parsed = match ? JSON.parse(match[0]) : {};
153	    return {
154	      message: String(parsed.message || raw),
155	      actions: Array.isArray(parsed.actions) ? parsed.actions : [],
156	      source: "primary",
157	    };
158	  } catch (err) {
159	    console.error("Primary AI error:", err);
160	    return null;
161	  }
162	}
