298	function fallbackResponse(
299	  userMessage: string,
300	  ctx: StudentContext,
301	  history: ChatMessage[],
302	  notifications?: string,
303	): AIChatResult {
304	  const input = userMessage.trim();
305	  const actions: AIAction[] = [];
306	  let message = "";
307	
308	  const { state, data } = getMenuState(history);
309	
310	  // ── Back to menu from any state ──
311	  if (input === "0" || input.includes("رجوع") || input.includes("القائمة")) {
312	    return { message: buildMainMenu(ctx, notifications), actions: [], source: "fallback" };
313	  }
314	
315	  // ── State: Grade - Select Quiz (3a) ──
316	  if (state === "3a") {
317	    const code = input.toUpperCase().replace(/\s/g, "");
318	    const allQuizzes = ctx.courses.flatMap((c) =>
319	      c.quizResults.filter((q) => q.date).map((q) => ({
320	        quizId: q.quizId, quizTitle: q.quizTitle, courseTitle: c.title,
321	        code: q.quizId.slice(-8).toUpperCase(), percentage: q.percentage,
322	      }))
323	    );
324	    const selected = allQuizzes.find((q) => q.code === code || (code.length >= 4 && q.code.includes(code)));
325	    if (selected) {
326	      message = `✅ ${selected.quizTitle} (${selected.courseTitle})\nدرجتك: ${Math.round(selected.percentage)}%\n\n⬇️ اكتب سبب التعديل بالتفصيل:\n• رقم السؤال\n• إجابتك الصحيحة\n• ليه تفتكر إنها صح\n\n💡 مثال: "سؤال 2 إجابتي ب وهي الصح لأن..."\n\nاكتب 0 للرجوع\n\n[م:3b:${selected.quizId}]`;
327	    } else {
328	      message = `❌ كود غلط. اكتب الكود من القائمة (8 حروف).\n\nاكتب 0 للرجوع\n\n[م:3a]`;
329	    }
330	    return { message, actions, source: "fallback" };
331	  }
332	
333	  // ── State: Grade - Write Reason (3b) ──
334	  if (state === "3b" && data) {
335	    if (input.length < 20) {
336	      message = `❌ السبب قصير (${input.length}/20 حرف). اكتب تفاصيل أكتر.\n\nاكتب 0 للرجوع\n\n[م:3b:${data}]`;
337	    } else {
338	      const staffCtx = buildChatContextForStaff(history, ctx);
339	      actions.push({
340	        type: "create_grade_request",
341	        payload: { quizId: data, reason: input, evidence: JSON.stringify(staffCtx) },
342	      });
343	      message = `✅ تم إرسال طلب تعديل الدرجة للمعلم!\n\n📋 السبب: ${input.slice(0, 80)}${input.length > 80 ? "..." : ""}\n\n⏳ المعلم هيراجع طلبك. اكتب 5 لمتابعة الحالة.\n\nاكتب 0 للرجوع\n\n[م:menu]`;
