565	export async function chatWithAI(
566	  userMessage: string,
567	  history: ChatMessage[],
568	  studentContext: StudentContext,
569	  notifications?: string,
570	): Promise<AIChatResult> {
571	  const contextSummary = summarizeContext(studentContext);
572	  const cleanHistory = history.slice(-10).map((m) => ({
573	    role: m.role,
574	    content: stripFallbackMarkers(m.content),
575	  })).filter((m) => m.content.length > 0);
576	  const messages: ChatMessage[] = [
577	    { role: "system", content: `${SYSTEM_PROMPT}\n\n${contextSummary}` },
578	    ...cleanHistory,
579	    { role: "user", content: userMessage },
580	  ];
581	
582	  // 1. Try Gemini first
583	  let result = await callBackup(messages);
584	  if (result) return result;
585	
586	  // 2. Try Primary / DeepSeek
587	  result = await callPrimary(messages);
588	  if (result) return result;
589	
590	  // 3. Smart menu fallback (always runs when no AI key configured)
591	  return fallbackResponse(userMessage, studentContext, history, notifications);
