594	export async function analyzeQuizAnswer(
595	  question: string,
596	  studentAnswer: string,
597	  correctAnswer: string,
598	  options: Record<string, string>
599	): Promise<{ wasMisgraded: boolean; reasoning: string; confidence: number }> {
600	  const prompt = `حلل سؤال الكويز ده:
601	
602	السؤال: ${question}
603	خيارات: ${JSON.stringify(options, null, 2)}
604	إجابة المتعلم: ${studentAnswer}
605	الإجابة المعتمدة: ${correctAnswer}
606	
607	هل إجابة المتعلم فعلاً غلط؟ أو ممكن تكون صحيحة من ناحية أخرى؟ ممكن السؤال يكون غامض؟
608	
609	رد بـ JSON:
610	{
611	  "wasMisgraded": boolean,
612	  "reasoning": "سبب القرار بالعربي",
613	  "confidence": 0-1
614	}`;
615	
616	  const messages: ChatMessage[] = [
617	    { role: "system", content: "أنت مدرس خبير تحلل أسئلة الكويزات بدقة. ترد بـ JSON فقط." },
618	    { role: "user", content: prompt },
619	  ];
620	
621	  const result = await callPrimary(messages);
622	  if (result?.message) {
623	    try {
