634	      // Fall through
635	    }
636	  }
637	
638	  return {
639	    wasMisgraded: false,
640	    reasoning: "لم نتمكن من تحليل السؤال تلقائياً، يرجى مراجعة المعلم",
641	    confidence: 0,
642	  };
