68	export async function buildStudentContext(studentId: string): Promise<StudentContext> {
69	  const student = await prisma.user.findUnique({
70	    where: { id: studentId },
71	    select: {
72	      id: true,
73	      name: true,
74	      email: true,
75	      age: true,
76	      educationalStage: true,
77	      phone: true,
78	    },
79	  });
80	
81	  if (!student) {
82	    throw new Error("Student not found");
83	  }
84	
85	  // Get all courses the student has access to
86	  const accessCodes = await prisma.accessCode.findMany({
87	    where: { studentId },
88	    include: {
89	      course: {
90	        include: {
91	          teacher: { select: { name: true } },
92	          folders: {
93	            include: {
94	              videos: true,
95	              quizzes: {
96	                include: {
97	                  questions: true,
98	                  results: {
99	                    where: { studentId },
100	                  },
101	                },
102	              },
103	            },
104	          },
105	          _count: {
106	            select: {
107	              folders: true,
108	            },
109	          },
110	        },
111	      },
112	    },
113	  });
114	
115	  const courseContexts = await Promise.all(
116	    accessCodes.map(async (code) => {
117	      const course = code.course;
118	      const allVideos = course.folders.flatMap((f) => f.videos);
119	      const allQuizzes = course.folders.flatMap((f) => f.quizzes);
120	
121	      // Get video progress
122	      const videoIds = allVideos.map((v) => v.id);
123	      const progress = await prisma.progress.findMany({
124	        where: {
125	          studentId,
126	          videoId: { in: videoIds },
127	          watched: true,
128	        },
129	      });
130	      const watchedCount = progress.length;
131	
132	      // Get quiz results
133	      const quizResults = allQuizzes.map((quiz) => {
134	        const result = quiz.results[0];
135	        const percentage = result ? clampPercentage(result.score) : 0;
136	        return {
137	          quizId: quiz.id,
138	          quizTitle: quiz.title,
139	          score: percentage,
140	          totalQ: result?.totalQ ?? quiz.questions.length,
141	          percentage,
142	          date: result?.completedAt?.toISOString() ?? null,
143	        };
144	      });
145	
146	      return {
147	        id: course.id,
148	        title: course.title,
149	        subject: course.subject,
150	        teacher: course.teacher.name,
151	        progress: {
152	          videosWatched: watchedCount,
153	          totalVideos: allVideos.length,
154	          percentage: allVideos.length > 0
155	            ? Math.round((watchedCount / allVideos.length) * 100)
156	            : 0,
157	        },
158	        quizResults,
159	        lastAccessed: progress.length > 0
160	          ? progress[progress.length - 1].watchedAt?.toISOString() ?? null
161	          : null,
162	      };
163	    })
164	  );
165	
166	  // Calculate overall stats
167	  const allQuizResults = courseContexts.flatMap((c) => c.quizResults).filter((q) => q.date);
168	  const totalScore = allQuizResults.reduce((sum, q) => sum + q.percentage, 0);
169	  const averageScore = allQuizResults.length > 0
170	    ? clampPercentage(totalScore / allQuizResults.length)
171	    : 0;
172	
173	  const watchedVideos = courseContexts.reduce(
174	    (sum, c) => sum + c.progress.videosWatched,
175	    0
176	  );
177	
178	  // Identify weak areas
179	  const weakAreas: StudentContext["weakAreas"] = [];
180	  for (const course of courseContexts) {
181	    const lowScoreQuizzes = course.quizResults.filter((q) => q.percentage < 60);
182	    for (const quiz of lowScoreQuizzes) {
183	      weakAreas.push({
184	        subject: course.subject,
185	        topic: quiz.quizTitle,
186	        reason: `Low score: ${Math.round(quiz.percentage)}%`,
187	        evidence: `Quiz "${quiz.quizTitle}" - ${quiz.score}/${quiz.totalQ} correct`,
188	      });
189	    }
190	    // Also flag low video progress
191	    if (course.progress.percentage < 50 && course.progress.totalVideos > 0) {
192	      weakAreas.push({
193	        subject: course.subject,
194	        topic: "Course Progress",
195	        reason: "Low video completion",
196	        evidence: `Only ${course.progress.videosWatched}/${course.progress.totalVideos} videos watched`,
197	      });
198	    }
199	  }
200	
201	  // Get AI insights
202	  const aiInsights = await prisma.aIStudentInsight.findMany({
203	    where: { studentId },
204	    orderBy: { createdAt: "desc" },
205	    take: 10,
206	    select: {
207	      type: true,
208	      title: true,
209	      description: true,
210	      confidence: true,
211	    },
212	  });
213	
214	  // Get recent feedback
215	  const recentFeedback = await prisma.studentFeedback.findMany({
216	    where: { studentId },
217	    orderBy: { createdAt: "desc" },
218	    take: 5,
219	    include: { course: { select: { title: true } } },
220	  });
221	
222	  // Build library progress
223	  const libraryProgress = accessCodes.map((code) => ({
224	    folder: code.course.title,
225	    videos: code.course.folders.flatMap((f) =>
226	      f.videos.map((v) => v.title)
227	    ),
228	    quizzes: code.course.folders.flatMap((f) =>
229	      f.quizzes.map((q) => q.title)
230	    ),
231	  }));
232	
233	  return {
234	    profile: {
235	      id: student.id,
236	      name: student.name,
237	      email: student.email,
238	      age: student.age,
239	      educationalStage: student.educationalStage,
240	      phone: student.phone,
241	    },
242	    courses: courseContexts,
243	    overallStats: {
244	      totalCourses: courseContexts.length,
245	      averageScore,
246	      totalQuizzesTaken: allQuizResults.length,
247	      totalVideosWatched: watchedVideos,
248	    },
249	    weakAreas,
250	    aiInsights,
251	    recentFeedback: recentFeedback.map((f) => ({
252	      type: f.type,
253	      content: f.content,
254	      course: f.course.title,
255	      date: f.createdAt.toISOString(),
256	    })),
257	    libraryProgress,
258	  };
259	}
