281	export async function buildTeacherContext(teacherId: string): Promise<TeacherContext> {
282	  const teacher = await prisma.user.findUnique({
283	    where: { id: teacherId },
284	    select: {
285	      id: true,
286	      name: true,
287	      email: true,
288	    },
289	  });
290	
291	  if (!teacher) {
292	    throw new Error("Teacher not found");
293	  }
294	
295	  const courses = await prisma.course.findMany({
296	    where: { teacherId },
297	    include: {
298	      _count: {
299	        select: { accessCodes: true },
300	      },
301	      folders: {
302	        include: {
303	          quizzes: {
304	            include: {
305	              results: true,
306	            },
307	          },
308	        },
309	      },
310	    },
311	  });
312	
313	  const courseContexts = courses.map((course) => {
314	    const allResults = course.folders.flatMap((f: typeof course.folders[number]) =>
315	      f.quizzes.flatMap((q) => q.results)
316	    );
317	    const avgScore =
318	      allResults.length > 0
319	        ? allResults.reduce((sum, r) => sum + (r.score / r.totalQ) * 100, 0) /
320	          allResults.length
321	        : 0;
322	
323	    return {
324	      id: course.id,
325	      title: course.title,
326	      subject: course.subject,
327	      totalStudents: course._count.accessCodes,
328	      averageScore: Math.round(avgScore),
329	    };
330	  });
331	
332	  // Count pending requests
333	  const [gradeAdjustments, supportTickets, feedbackItems] = await Promise.all([
334	    prisma.gradeAdjustmentRequest.count({
335	      where: {
336	        courseId: { in: courses.map((c) => c.id) },
337	        status: { in: ["pending", "ai_reviewed"] },
338	      },
339	    }),
340	    prisma.supportTicket.count({
341	      where: {
342	        courseId: { in: courses.map((c) => c.id) },
343	        status: { in: ["open", "ai_handling", "escalated"] },
344	      },
345	    }),
346	    prisma.studentFeedback.count({
347	      where: {
348	        courseId: { in: courses.map((c) => c.id) },
349	        isResolved: false,
350	      },
351	    }),
352	  ]);
353	
354	  return {
355	    profile: {
356	      id: teacher.id,
357	      name: teacher.name,
358	      email: teacher.email,
359	    },
360	    courses: courseContexts,
361	    pendingRequests: {
362	      gradeAdjustments,
363	      supportTickets,
364	      feedbackItems,
365	    },
366	  };
367	}

