12	// GET — return existing insights + auto-refresh if older than 24h
13	export async function GET() {
14	  try {
15	    const session = await getStudentSession();
16	    if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
17	
18	    const existing = await prisma.aIStudentInsight.findMany({
19	      where: { studentId: session.id },
20	      orderBy: { createdAt: "desc" },
21	      take: 10,
22	    });
23	
24	    const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
25	    const hasBadInsight = existing.some((i) => hasInvalidPercentage(`${i.title} ${i.description}`));
26	    const stale = existing.length === 0 || existing[0].createdAt < oneDayAgo || hasBadInsight;
27	
28	    if (stale) {
29	      const ctx = await buildStudentContext(session.id);
30	      const fresh = await generateInsights(ctx);
31	      if (hasBadInsight) {
32	        await prisma.aIStudentInsight.deleteMany({ where: { studentId: session.id } });
33	      }
34	      const created = await Promise.all(
35	        fresh.map((i) =>
36	          prisma.aIStudentInsight.create({
37	            data: {
38	              studentId: session.id,
39	              type: i.type,
40	              category: i.category,
41	              title: i.title,
42	              description: i.description,
43	              confidence: i.confidence,
44	              dataSnapshot: JSON.stringify({
45	                averageScore: ctx.overallStats.averageScore,
46	                courses: ctx.overallStats.totalCourses,
47	                weakAreas: ctx.weakAreas.length,
48	              }),
49	            },
50	          })
51	        )
52	      );
53	      return NextResponse.json({ insights: created, refreshed: true });
54	    }
55	
56	    return NextResponse.json({ insights: existing, refreshed: false });
57	  } catch (err) {
58	    console.error("Insights GET error:", err);
59	    return NextResponse.json({ error: "حدث خطأ" }, { status: 500 });
60	  }
61	}
